  if (typeof phrase === "string") return phrase;
  if (typeof phrase.key !== "string" || phrase.key.trim().length === 0) {
    throw new TypeError("phrase key must be non-blank");
  }
  const template = Object.prototype.hasOwnProperty.call(dictionary, phrase.key)
    ? dictionary[phrase.key]
    : phrase.key;
  return template.replace(/\{([^{}]+)\}/g, (token, name: string) =>
    phrase.values && Object.prototype.hasOwnProperty.call(phrase.values, name)
      ? String(phrase.values[name])
      : token,
  );
}

export function localizeMeta(meta: DocumentMeta, dictionary: Dictionary): LocalizedMeta {
  const result = {
    title: resolvePhrase(meta.title, dictionary),
    summary: resolvePhrase(meta.summary, dictionary),
  };
  return result;
}

export function loadLocalizedResource(
  addresses: Readonly<Record<number, string>>,
  language: number,
  meta: DocumentMeta,
  dictionary: Dictionary,
): Promise<LocalizedResource> {
  if (!Number.isInteger(language) || language < 0) {
    throw new RangeError("language must be a non-negative integer");
  }
  const address = addresses[language];
  if (typeof address !== "string" || address.trim().length === 0) {
    return Promise.resolve(Object.freeze({ state: LoadState.Missing }));
  }
  return Promise.resolve(Object.freeze({
    state: LoadState.Ready,
    address,
    meta: localizeMeta(meta, dictionary),
  }));
}

