import { LoadState, localizeMeta, loadLocalizedResource, type DocumentMeta, type Phrase } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (actual !== expected) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function expectTypeError(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) { if (error instanceof TypeError) return; throw new Error(`${message}: wrong error type`); }
  throw new Error(`${message}: did not throw`);
}

const values: Record<string, string | number> = { name: 'Ada', count: 2 };
const dictionary: Record<string, string> = {
  title: 'Hello {name}, {name}! {missing}',
  summary: '{count} items for {name}',
};
const meta: DocumentMeta = {
  title: { key: 'title', values },
  summary: { key: 'summary', values },
};
const localized = localizeMeta(meta, dictionary);
equal(localized.title, 'Hello Ada, Ada! {missing}', 'repeated and unmatched tokens');
equal(localized.summary, '2 items for Ada', 'numeric substitutions use String');
assert(Object.isFrozen(localized), 'localized metadata is frozen');
values.name = 'Changed';
dictionary.title = 'Changed';
equal(localized.title, 'Hello Ada, Ada! {missing}', 'localized result is stable after input mutation');

const literals = localizeMeta({ title: '', summary: '  exact  ' }, {});
equal(literals.title, '', 'empty string phrase is allowed');
equal(literals.summary, '  exact  ', 'string phrase is preserved exactly');
const fallback = localizeMeta({ title: { key: 'missing.key' }, summary: { key: 'Hi {who}', values: { who: 'Sam' } } }, {});
equal(fallback.title, 'missing.key', 'missing key falls back to key');
equal(fallback.summary, 'Hi Sam', 'fallback text also receives substitutions');
expectTypeError(() => localizeMeta({ title: { key: ' ' }, summary: 'x' }, {}), 'blank phrase key');
expectTypeError(() => localizeMeta({ title: { key: 3 } as unknown as Phrase, summary: 'x' }, {}), 'non-string phrase key');

void (async (): Promise<void> => {
  const ready = await loadLocalizedResource({ 1: '  /resource  ' }, 1, meta, dictionary);
  equal(ready.state, LoadState.Ready, 'valid address is ready');
  equal(ready.address, '  /resource  ', 'address is preserved exactly');
  assert(ready.meta !== undefined, 'ready resource has metadata');
  equal(ready.meta?.summary, '2 items for Changed', 'ready resource localizes metadata');
  assert(Object.isFrozen(ready), 'ready resource is frozen');
  assert(Object.isFrozen(ready.meta as object), 'nested metadata is frozen');

  const invalidMeta: DocumentMeta = { title: { key: ' ' }, summary: 'x' };
  const missing = await loadLocalizedResource({}, 2, invalidMeta, {});
  equal(missing.state, LoadState.Missing, 'absent address is missing');
  equal(missing.address, undefined, 'missing resource omits address');
  equal(missing.meta, undefined, 'missing resource omits metadata');
  assert(Object.isFrozen(missing), 'missing resource is frozen');

  const blank = await loadLocalizedResource({ 2: ' \t ' }, 2, invalidMeta, {});
  equal(blank.state, LoadState.Missing, 'blank address is missing without localization');
  const malformed = await loadLocalizedResource({ 2: 42 as unknown as string }, 2, invalidMeta, {});
  equal(malformed.state, LoadState.Missing, 'non-string address is missing');

  for (const language of [-1, 1.5, Number.NaN]) {
    let rejected = false;
    try { await loadLocalizedResource({}, language, { title: '', summary: '' }, {}); }
    catch (error) { rejected = error instanceof RangeError; }
    assert(rejected, `invalid language ${String(language)} rejects with RangeError`);
  }
})();

